import { describe, test, expect } from 'vitest';
/**
 * JjEL bit-vectors against the Verilator oracle (R-BV-10). The table
 * `fixtures/bv-cases.json` is generated by `scripts/oracle/bv-cases.mjs` and its
 * `expected` values are written by `scripts/oracle/bv-verilator.mjs` from a
 * Verilator run, never from the evaluator. This test needs no Verilator: it
 * evaluates every row through JjEL and compares with the committed values.
 * Regenerate with `npm run oracle:bv`.
 */

import { jjelEval } from '../index';
import type { JjelValue } from '../evaluator';
import { isBitVector } from '../evaluator/context';
import table from './fixtures/bv-cases.json';

interface CaseRow {
    i: number;
    op: string;
    w: number;
    s: boolean;
    a: string;
    b?: string;
    rest?: [number, string][];
    args?: number[];
    rw: number;
    expected?: string;
    /** A row on which the evaluator and Verilator disagree, listed and left for a decision. */
    skip?: string;
}

const rows = (table as unknown as { rows: CaseRow[] }).rows;
const inexpressible = (table as unknown as { oracle: { inexpressible: { i: number }[] } }).oracle.inexpressible;

/** The JjEL expression of each operator, over the context variables a, b, c, d. */
const EXPR: Record<string, (r: CaseRow) => string> = {
    add: () => 'a + b', sub: () => 'a - b', mul: () => 'a * b', neg: () => '-a',
    eq: () => 'a == b', ne: () => 'a != b', lt: () => 'a < b', le: () => 'a <= b', gt: () => 'a > b', ge: () => 'a >= b',
    and: () => 'a.and(b)', or: () => 'a.or(b)', xor: () => 'a.xor(b)', not: () => 'a.not()',
    shl: r => `a.shl(${r.args![0]})`, shr: r => `a.shr(${r.args![0]})`, ashr: r => `a.ashr(${r.args![0]})`,
    slice: r => `a.slice(${r.args![0]}, ${r.args![1]})`, bit: r => `a.bit(${r.args![0]})`,
    concat: r => `a.concat(${r.rest!.map((_, k) => 'cd'[k]).join(', ')})`, replicate: r => `a.replicate(${r.args![0]})`,
    zext: r => `a.zext(${r.args![0]})`, sext: r => `a.sext(${r.args![0]})`, trunc: r => `a.trunc(${r.args![0]})`,
};

const COMPARISONS = new Set(['eq', 'ne', 'lt', 'le', 'gt', 'ge']);

function vector(w: number, s: boolean, hex: string): JjelValue {
    return jjelEval(`${s ? 'sbits' : 'bits'}(${w}, '0x${hex}')`);
}

/** The evaluator's answer in the oracle's notation: hex padded to the result width, or 0/1. */
function evaluateRow(r: CaseRow): string {
    const ctx: Record<string, JjelValue> = { a: vector(r.w, r.s, r.a) };
    if (r.b !== undefined) ctx.b = vector(r.w, r.s, r.b);
    r.rest?.forEach(([w, hex], k) => { ctx['cd'[k]] = vector(w, false, hex); });
    const v = jjelEval(EXPR[r.op](r), ctx);
    if (COMPARISONS.has(r.op)) {
        if (typeof v !== 'boolean') return `not a boolean: ${String(v)}`;
        return v ? '1' : '0';
    }
    if (!isBitVector(v)) return `not a bit-vector: ${String(v)}`;
    if (v.width !== r.rw) return `width ${v.width}, expected ${r.rw}`;
    return v.bits.toString(16).padStart(Math.ceil(v.width / 4), '0');
}

const operators = [...new Set(rows.map(r => r.op))];

describe('Verilator oracle (bv-cases.json)', () => {
    test('covers every S1 operator and method, under about 5000 rows', () => {
        expect([...operators].sort()).toEqual(Object.keys(EXPR).sort());
        expect(rows.length).toBeGreaterThan(4000);
        expect(rows.length).toBeLessThanOrEqual(5000);
        rows.forEach((r, k) => expect(r.i).toBe(k));
    });

    test('every row has a Verilator value or is listed as inexpressible', () => {
        const listed = new Set(inexpressible.map(x => x.i));
        const bare = rows.filter(r => r.expected === undefined && !listed.has(r.i)).map(r => r.i);
        expect(bare).toEqual([]);
    });

    test.each(operators.map(op => [op]))('%s agrees with Verilator row by row', op => {
        const mine = rows.filter(r => r.op === op && r.expected !== undefined && r.skip === undefined);
        expect(mine.length).toBeGreaterThan(0);
        const disagreements = mine
            .map(r => ({ i: r.i, got: evaluateRow(r), expected: r.expected }))
            .filter(d => d.got !== d.expected);
        expect(disagreements).toEqual([]);
    });
});
